 31→/**
 32→ * Non-instantiable namespace class containing concrete {@link VectorIndex} implementations backed
 33→ * by an {@link LsmTree}.
 34→ *
 35→ * <ul>
 36→ * <li>{@link IvfFlat} — Inverted File with Flat re-scoring. Uses three key namespaces within one
 37→ * {@link LsmTree}: centroid coordinates {@code [0x00]}, posting-list entries {@code [0x01]}, and
 38→ * reverse-lookup entries {@code [0x02]}.</li>
 39→ * <li>{@link Hnsw} — Hierarchical Navigable Small World graph. Uses doc-id bytes as node keys,
 40→ * {@code [0xFE]} for the entry point, and {@code [0xFF][docId]} for soft-deletes.</li>
 41→ * </ul>
 42→ *
 43→ * <p>
 44→ * All similarity computations are accelerated with {@code FloatVector.SPECIES_PREFERRED} from
 45→ * {@code jdk.incubator.vector}, with a scalar tail loop for dimensions not covered by the SIMD
 46→ * width.
 47→ *
 48→ * <p>
 49→ * Obtain instances via {@link #ivfFlatBuilder()} and {@link #hnswBuilder()}.
 50→ */
 51→public final class LsmVectorIndex {
 52→
 53→    // Preferred SIMD species for float computation
 54→    private static final VectorSpecies<Float> SPECIES = FloatVector.SPECIES_PREFERRED;
 55→
 56→    private LsmVectorIndex() {
 57→        throw new UnsupportedOperationException("utility class");
 58→    }
 59→
 60→    // -----------------------------------------------------------------------
 61→    // Factory methods
 62→    // -----------------------------------------------------------------------
 63→
 64→    /** Returns a builder for an {@link IvfFlat} vector index backed by an {@link LsmTree}. */
 65→    public static <D> IvfFlat.Builder<D> ivfFlatBuilder() {
 66→        return new IvfFlat.Builder<>();
 67→    }
 68→
 69→    /** Returns a builder for an {@link Hnsw} vector index backed by an {@link LsmTree}. */
 70→    public static <D> Hnsw.Builder<D> hnswBuilder() {
 71→        return new Hnsw.Builder<>();
 72→    }
 73→
 74→    // -----------------------------------------------------------------------
 75→    // Float encoding helpers
 76→    // -----------------------------------------------------------------------
 77→
 78→    static byte[] encodeFloats(float[] floats) {
 79→        assert floats != null : "floats must not be null";
 80→        byte[] bytes = new byte[floats.length * 4];
 81→        for (int i = 0; i < floats.length; i++) {
 82→            int bits = Float.floatToRawIntBits(floats[i]);
 83→            bytes[i * 4] = (byte) (bits >>> 24);
 84→            bytes[i * 4 + 1] = (byte) (bits >>> 16);
 85→            bytes[i * 4 + 2] = (byte) (bits >>> 8);
 86→            bytes[i * 4 + 3] = (byte) bits;
 87→        }
 88→        return bytes;
 89→    }
 90→
 91→    static float[] decodeFloats(byte[] bytes, int dimensions) {
 92→        assert bytes != null : "bytes must not be null";
 93→        assert bytes.length == dimensions * 4 : "byte count mismatch";
 94→        float[] floats = new float[dimensions];
 95→        for (int i = 0; i < dimensions; i++) {
 96→            int bits = ((bytes[i * 4] & 0xFF) << 24) | ((bytes[i * 4 + 1] & 0xFF) << 16)
 97→                    | ((bytes[i * 4 + 2] & 0xFF) << 8) | (bytes[i * 4 + 3] & 0xFF);
 98→            floats[i] = Float.intBitsToFloat(bits);
 99→        }
100→        return floats;
101→    }
102→
103→    // -----------------------------------------------------------------------
104→    // Float16 encoding helpers
105→    // -----------------------------------------------------------------------
106→
107→    /**
108→     * Encodes a float array to float16 (IEEE 754 binary16) big-endian bytes. Contract: each float
109→     * is converted via {@link Float#floatToFloat16(float)} and stored as 2 bytes big-endian. Output
110→     * length is {@code floats.length * 2}. Side effects: none.
111→     *
112→     * @param floats the float array to encode; must not be null
113→     * @return big-endian float16 byte array of length {@code floats.length * 2}
114→     */
115→    static byte[] encodeFloat16s(float[] floats) {
116→        assert floats != null : "floats must not be null";
117→        byte[] bytes = new byte[floats.length * 2];
118→        for (int i = 0; i < floats.length; i++) {
119→            short bits = Float.floatToFloat16(floats[i]);
120→            bytes[i * 2] = (byte) (bits >>> 8);
121→            bytes[i * 2 + 1] = (byte) bits;
122→        }
123→        return bytes;
124→    }
125→
126→    /**
127→     * Decodes big-endian float16 bytes back to a float array. Contract: each 2-byte pair is read as
128→     * a big-endian short, converted to float via {@link Float#float16ToFloat(short)}. Input length
129→     * must equal {@code dimensions * 2}. Side effects: none.
130→     *
131→     * @param bytes the float16 byte array; must not be null
132→     * @param dimensions the expected number of float components
133→     * @return float array of length {@code dimensions}
134→     */
135→    static float[] decodeFloat16s(byte[] bytes, int dimensions) {
136→        assert bytes != null : "bytes must not be null";
137→        assert bytes.length == dimensions * 2 : "byte count mismatch";
138→        float[] floats = new float[dimensions];
139→        for (int i = 0; i < dimensions; i++) {
140→            short bits = (short) (((bytes[i * 2] & 0xFF) << 8) | (bytes[i * 2 + 1] & 0xFF));
141→            floats[i] = Float.float16ToFloat(bits);
142→        }
143→        return floats;
144→    }
145→
146→    /**
147→     * Encodes a float vector using the specified precision. Contract: dispatches to
148→     * {@link #encodeFloats(float[])} for FLOAT32 or {@link #encodeFloat16s(float[])} for FLOAT16.
149→     * Side effects: none.
150→     *
151→     * @param floats the float array to encode; must not be null
152→     * @param precision the target precision; must not be null
153→     * @return encoded byte array
154→     */
155→    static byte[] encodeVector(float[] floats, VectorPrecision precision) {
156→        assert floats != null : "floats must not be null";
157→        assert precision != null : "precision must not be null";
158→        return switch (precision) {
159→            case FLOAT32 -> encodeFloats(floats);
160→            case FLOAT16 -> encodeFloat16s(floats);
161→        };
162→    }
163→
164→    /**
165→     * Decodes a vector from bytes using the specified precision, returning float[]. Contract:
166→     * dispatches to {@link #decodeFloats(byte[], int)} for FLOAT32 or
167→     * {@link #decodeFloat16s(byte[], int)} for FLOAT16. Side effects: none.
168→     *
169→     * @param bytes the encoded byte array; must not be null
170→     * @param dimensions the expected number of float components
171→     * @param precision the source precision; must not be null
172→     * @return float array of length {@code dimensions}
173→     */
174→    static float[] decodeVector(byte[] bytes, int dimensions, VectorPrecision precision) {
175→        assert bytes != null : "bytes must not be null";
176→        assert precision != null : "precision must not be null";
177→        return switch (precision) {
178→            case FLOAT32 -> decodeFloats(bytes, dimensions);
179→            case FLOAT16 -> decodeFloat16s(bytes, dimensions);
180→        };
181→    }
182→
183→    // -----------------------------------------------------------------------
184→    // SIMD similarity functions
185→    // -----------------------------------------------------------------------
186→
187→    /** Returns the dot product of two float vectors using SIMD + scalar tail. */
188→    static float dotProduct(float[] a, float[] b) {
189→        assert a != null && b != null : "vectors must not be null";
190→        assert a.length == b.length : "vectors must have the same length";
191→        int i = 0, ub = SPECIES.loopBound(a.length);
192→        var acc = FloatVector.zero(SPECIES);
193→        for (; i < ub; i += SPECIES.length()) {
194→            acc = FloatVector.fromArray(SPECIES, a, i).fma(FloatVector.fromArray(SPECIES, b, i),
195→                    acc);
196→        }
197→        float sum = acc.reduceLanes(VectorOperators.ADD);
198→        for (; i < a.length; i++)
199→            sum += a[i] * b[i];
200→        return sum;

