  1→package jlsm.table.internal;
  2→
  3→import java.io.Closeable;
  4→import java.io.IOException;
  5→import java.lang.foreign.Arena;
  6→import java.lang.foreign.MemorySegment;
  7→import java.lang.foreign.ValueLayout;
  8→import java.util.ArrayList;
  9→import java.util.Arrays;
 10→import java.util.Iterator;
 11→import java.util.LinkedHashMap;
 12→import java.util.List;
 13→import java.util.Map;
 14→import java.util.Objects;
 15→
 16→import jlsm.table.FieldDefinition;
 17→import jlsm.table.FieldType;
 18→import jlsm.table.IndexDefinition;
 19→import jlsm.table.IndexType;
 20→import jlsm.table.JlsmDocument;
 21→import jlsm.table.JlsmSchema;
 22→import jlsm.table.Predicate;
 23→
 24→/**
 25→ * Manages all secondary indices for a table. Routes write operations to the appropriate indices and
 26→ * provides index lookup for query execution.
 27→ */
 28→public final class IndexRegistry implements Closeable {
 29→
 30→    private final JlsmSchema schema;
 31→    private final List<SecondaryIndex> indices;
 32→    private final Map<PkKey, StoredEntry> documentStore;
 33→    private volatile boolean closed;
 34→
 35→    public IndexRegistry(JlsmSchema schema, List<IndexDefinition> definitions) throws IOException {
 36→        Objects.requireNonNull(schema, "schema");
 37→        Objects.requireNonNull(definitions, "definitions");
 38→        this.schema = schema;
 39→        this.indices = new ArrayList<>();
 40→        this.documentStore = new LinkedHashMap<>();
 41→
 42→        for (IndexDefinition def : definitions) {
 43→            validate(schema, def);
 44→            this.indices.add(createIndex(def));
 45→        }
 46→    }
 47→
 48→    public void onInsert(MemorySegment primaryKey, JlsmDocument document) throws IOException {
 49→        assert !closed : "Registry is closed";
 50→        Objects.requireNonNull(primaryKey, "primaryKey");
 51→        Objects.requireNonNull(document, "document");
 52→
 53→        // Unique checks first
 54→        for (SecondaryIndex idx : indices) {
 55→            if (idx.definition().indexType() == IndexType.UNIQUE) {
 56→                Object fieldValue = extractFieldValue(document, idx.definition().fieldName());
 57→                idx.onInsert(primaryKey, fieldValue);
 58→            }
 59→        }
 60→        // Non-unique inserts
 61→        for (SecondaryIndex idx : indices) {
 62→            if (idx.definition().indexType() != IndexType.UNIQUE) {
 63→                Object fieldValue = extractFieldValue(document, idx.definition().fieldName());
 64→                idx.onInsert(primaryKey, fieldValue);
 65→            }
 66→        }
 67→
 68→        documentStore.put(toPkKey(primaryKey), new StoredEntry(copySegment(primaryKey), document));
 69→    }
 70→
 71→    public void onUpdate(MemorySegment primaryKey, JlsmDocument oldDocument,
 72→            JlsmDocument newDocument) throws IOException {
 73→        assert !closed : "Registry is closed";
 74→        for (SecondaryIndex idx : indices) {
 75→            String fieldName = idx.definition().fieldName();
 76→            Object oldValue = oldDocument != null ? extractFieldValue(oldDocument, fieldName)
 77→                    : null;
 78→            Object newValue = extractFieldValue(newDocument, fieldName);
 79→            idx.onUpdate(primaryKey, oldValue, newValue);
 80→        }
 81→
 82→        documentStore.put(toPkKey(primaryKey),
 83→                new StoredEntry(copySegment(primaryKey), newDocument));
 84→    }
 85→
 86→    public void onDelete(MemorySegment primaryKey, JlsmDocument document) throws IOException {
 87→        assert !closed : "Registry is closed";
 88→        for (SecondaryIndex idx : indices) {
 89→            Object fieldValue = extractFieldValue(document, idx.definition().fieldName());
 90→            idx.onDelete(primaryKey, fieldValue);
 91→        }
 92→
 93→        documentStore.remove(toPkKey(primaryKey));
 94→    }
 95→
 96→    public SecondaryIndex findIndex(Predicate predicate) {
 97→        for (SecondaryIndex idx : indices) {
 98→            if (idx.supports(predicate)) {
 99→                return idx;
100→            }
101→        }
102→        return null;
103→    }
104→
105→    public boolean isEmpty() {
106→        return indices.isEmpty();
107→    }
108→
109→    @Override
110→    public void close() throws IOException {
111→        closed = true;
112→        IOException deferred = null;
113→        for (SecondaryIndex idx : indices) {
114→            try {
115→                idx.close();
116→            } catch (IOException e) {
117→                if (deferred == null) {
118→                    deferred = e;
119→                } else {
120→                    deferred.addSuppressed(e);
121→                }
122→            }
123→        }
124→        if (deferred != null) {
125→            throw deferred;
126→        }
127→    }
128→
129→    /**
130→     * Resolves a primary key to its stored document, or null if not found.
131→     */
132→    public StoredEntry resolveEntry(MemorySegment primaryKey) {
133→        return documentStore.get(toPkKey(primaryKey));
134→    }
135→
136→    /**
137→     * Returns an iterator over all stored entries. Used for scan-and-filter queries.
138→     */
139→    public Iterator<StoredEntry> allEntries() {
140→        return List.copyOf(documentStore.values()).iterator();
141→    }
142→
143→    /**
144→     * Returns the schema this registry was created with.
145→     */
146→    public JlsmSchema schema() {
147→        return schema;
148→    }
149→
150→    // ── Document store types ────────────────────────────────────────────
151→
152→    /**
153→     * A stored entry associating a primary key segment with its document.
154→     */
155→    public record StoredEntry(MemorySegment primaryKey, JlsmDocument document) {
156→        public StoredEntry {
157→            assert primaryKey != null : "primaryKey must not be null";
158→            assert document != null : "document must not be null";
159→        }
160→    }
161→
162→    /**
163→     * Byte-array wrapper with content-based equals/hashCode for use as map keys.
164→     */
165→    private record PkKey(byte[] data) {
166→        @Override
167→        public boolean equals(Object obj) {
168→            return obj instanceof PkKey other && Arrays.equals(this.data, other.data);
169→        }
170→
171→        @Override
172→        public int hashCode() {
173→            return Arrays.hashCode(data);
174→        }
175→    }
176→
177→    private static PkKey toPkKey(MemorySegment seg) {
178→        return new PkKey(seg.toArray(ValueLayout.JAVA_BYTE));
179→    }
180→
181→    private static MemorySegment copySegment(MemorySegment src) {
182→        MemorySegment copy = Arena.ofAuto().allocate(src.byteSize());
183→        copy.copyFrom(src);
184→        return copy;
185→    }
186→
187→    // ── Private helpers ─────────────────────────────────────────────────
188→
189→    private static void validate(JlsmSchema schema, IndexDefinition def) {
190→        int fieldIdx = schema.fieldIndex(def.fieldName());
191→        if (fieldIdx < 0) {
192→            throw new IllegalArgumentException("Field '" + def.fieldName()
193→                    + "' does not exist in schema '" + schema.name() + "'");
194→        }
195→
196→        FieldDefinition fieldDef = schema.fields().get(fieldIdx);
197→        FieldType fieldType = fieldDef.type();
198→
199→        switch (def.indexType()) {
200→            case RANGE, UNIQUE -> {
201→                if (fieldType == FieldType.Primitive.BOOLEAN) {
202→                    throw new IllegalArgumentException(
203→                            "RANGE/UNIQUE index is not supported on BOOLEAN field '"
204→                                    + def.fieldName() + "'");
205→                }
206→                if (!(fieldType instanceof FieldType.Primitive)) {
207→                    throw new IllegalArgumentException(
208→                            "RANGE/UNIQUE index requires a primitive field type, got: " + fieldType
209→                                    + " for field '" + def.fieldName() + "'");
210→                }
211→            }
212→            case EQUALITY -> {
213→                if (!(fieldType instanceof FieldType.Primitive)) {
214→                    throw new IllegalArgumentException(
215→                            "EQUALITY index requires a primitive field type, got: " + fieldType
216→                                    + " for field '" + def.fieldName() + "'");
217→                }
218→            }
219→            case FULL_TEXT -> {
220→                if (fieldType != FieldType.Primitive.STRING) {
221→                    throw new IllegalArgumentException(
222→                            "FULL_TEXT index requires STRING field, got: " + fieldType
223→                                    + " for field '" + def.fieldName() + "'");
224→                }
225→            }
226→            case VECTOR -> {
227→                if (!(fieldType instanceof FieldType.ArrayType at
228→                        && (at.elementType() == FieldType.Primitive.FLOAT32
229→                                || at.elementType() == FieldType.Primitive.FLOAT16))) {
230→                    throw new IllegalArgumentException(
231→                            "VECTOR index requires ArrayType(FLOAT32) or "
232→                                    + "ArrayType(FLOAT16) field, got: " + fieldType + " for field '"
233→                                    + def.fieldName() + "'");
234→                }
235→            }
236→        }
237→    }
238→
239→    private static SecondaryIndex createIndex(IndexDefinition def) throws IOException {
240→        return switch (def.indexType()) {
241→            case EQUALITY, RANGE, UNIQUE -> new FieldIndex(def);
242→            case FULL_TEXT -> new FullTextFieldIndex(def);
243→            case VECTOR -> new VectorFieldIndex(def);
244→        };
245→    }
246→
247→    private Object extractFieldValue(JlsmDocument document, String fieldName) {
248→        if (document.isNull(fieldName)) {
249→            return null;
250→        }
251→        int idx = schema.fieldIndex(fieldName);
252→        assert idx >= 0 : "Field must exist — validated at construction";
253→        FieldDefinition fieldDef = schema.fields().get(idx);
254→        FieldType fieldType = fieldDef.type();
255→
256→        if (fieldType instanceof FieldType.Primitive p) {
257→            return switch (p) {
258→                case STRING -> document.getString(fieldName);
259→                case INT8 -> document.getByte(fieldName);
260→                case INT16 -> document.getShort(fieldName);
261→                case INT32 -> document.getInt(fieldName);
262→                case INT64 -> document.getLong(fieldName);
263→                case FLOAT16 -> document.getFloat16Bits(fieldName);
264→                case FLOAT32 -> document.getFloat(fieldName);
265→                case FLOAT64 -> document.getDouble(fieldName);
266→                case BOOLEAN -> document.getBoolean(fieldName);
267→                case TIMESTAMP -> document.getTimestamp(fieldName);
268→            };
269→        } else if (fieldType instanceof FieldType.ArrayType) {
270→            return document.getArray(fieldName);
271→        } else if (fieldType instanceof FieldType.ObjectType) {
272→            return document.getObject(fieldName);
273→        }
274→        return null;
275→    }
276→}
