  1→package jlsm.table.internal;
  2→
  3→import java.io.IOException;
  4→import java.lang.foreign.Arena;
  5→import java.lang.foreign.MemorySegment;
  6→import java.lang.foreign.ValueLayout;
  7→import java.util.ArrayList;
  8→import java.util.Collections;
  9→import java.util.Iterator;
 10→import java.util.List;
 11→import java.util.NavigableMap;
 12→import java.util.Objects;
 13→import java.util.TreeMap;
 14→
 15→import jlsm.table.DuplicateKeyException;
 16→import jlsm.table.FieldType;
 17→import jlsm.table.IndexDefinition;
 18→import jlsm.table.IndexType;
 19→import jlsm.table.Predicate;
 20→
 21→/**
 22→ * Secondary index for equality, range, and unique lookups on a single field. Uses an in-memory
 23→ * sorted map where keys are sort-preserving encoded field values (via {@link FieldValueCodec}) and
 24→ * values are lists of primary keys.
 25→ */
 26→public final class FieldIndex implements SecondaryIndex {
 27→
 28→    private final IndexDefinition definition;
 29→    private final NavigableMap<ByteArrayKey, List<MemorySegment>> entries;
 30→    private volatile boolean closed;
 31→
 32→    public FieldIndex(IndexDefinition definition) throws IOException {
 33→        Objects.requireNonNull(definition, "definition");
 34→        IndexType type = definition.indexType();
 35→        assert type == IndexType.EQUALITY || type == IndexType.RANGE || type == IndexType.UNIQUE
 36→                : "FieldIndex only supports EQUALITY, RANGE, or UNIQUE";
 37→        this.definition = definition;
 38→        this.entries = new TreeMap<>();
 39→    }
 40→
 41→    @Override
 42→    public IndexDefinition definition() {
 43→        return definition;
 44→    }
 45→
 46→    @Override
 47→    public void onInsert(MemorySegment primaryKey, Object fieldValue) throws IOException {
 48→        assert !closed : "Index is closed";
 49→        if (fieldValue == null) {
 50→            return;
 51→        }
 52→        FieldType fieldType = inferFieldType(fieldValue);
 53→        ByteArrayKey encoded = encodeKey(fieldValue, fieldType);
 54→
 55→        if (definition.indexType() == IndexType.UNIQUE) {
 56→            List<MemorySegment> existing = entries.get(encoded);
 57→            if (existing != null && !existing.isEmpty()) {
 58→                throw new DuplicateKeyException(String.valueOf(fieldValue));
 59→            }
 60→        }
 61→
 62→        entries.computeIfAbsent(encoded, _ -> new ArrayList<>()).add(copySegment(primaryKey));
 63→    }
 64→
 65→    @Override
 66→    public void onUpdate(MemorySegment primaryKey, Object oldFieldValue, Object newFieldValue)
 67→            throws IOException {
 68→        assert !closed : "Index is closed";
 69→        if (oldFieldValue != null) {
 70→            removeEntry(primaryKey, oldFieldValue);
 71→        }
 72→        if (newFieldValue != null) {
 73→            onInsert(primaryKey, newFieldValue);
 74→        }
 75→    }
 76→
 77→    @Override
 78→    public void onDelete(MemorySegment primaryKey, Object fieldValue) throws IOException {
 79→        assert !closed : "Index is closed";
 80→        if (fieldValue == null) {
 81→            return;
 82→        }
 83→        removeEntry(primaryKey, fieldValue);
 84→    }
 85→
 86→    @Override
 87→    public Iterator<MemorySegment> lookup(Predicate predicate) throws IOException {
 88→        assert !closed : "Index is closed";
 89→        return switch (predicate) {
 90→            case Predicate.Eq eq -> lookupEq(eq.value());
 91→            case Predicate.Ne ne -> lookupNe(ne.value());
 92→            case Predicate.Gt gt -> lookupGt(gt.value());
 93→            case Predicate.Gte gte -> lookupGte(gte.value());
 94→            case Predicate.Lt lt -> lookupLt(lt.value());
 95→            case Predicate.Lte lte -> lookupLte(lte.value());
 96→            case Predicate.Between between -> lookupBetween(between.low(), between.high());
 97→            default -> Collections.emptyIterator();
 98→        };
 99→    }
100→
101→    @Override
102→    public boolean supports(Predicate predicate) {
103→        String field = predicateField(predicate);
104→        if (field == null || !field.equals(definition.fieldName())) {
105→            return false;
106→        }
107→        return switch (definition.indexType()) {
108→            case EQUALITY -> predicate instanceof Predicate.Eq || predicate instanceof Predicate.Ne;
109→            case RANGE, UNIQUE -> predicate instanceof Predicate.Eq
110→                    || predicate instanceof Predicate.Ne || predicate instanceof Predicate.Gt
111→                    || predicate instanceof Predicate.Gte || predicate instanceof Predicate.Lt
112→                    || predicate instanceof Predicate.Lte || predicate instanceof Predicate.Between;
113→            default -> false;
114→        };
115→    }
116→
117→    @Override
118→    public void close() throws IOException {
119→        closed = true;
120→        entries.clear();
121→    }
122→
123→    // ── Private helpers ─────────────────────────────────────────────────
124→
125→    private void removeEntry(MemorySegment primaryKey, Object fieldValue) {
126→        FieldType fieldType = inferFieldType(fieldValue);
127→        ByteArrayKey encoded = encodeKey(fieldValue, fieldType);
128→        List<MemorySegment> pks = entries.get(encoded);
129→        if (pks != null) {
130→            pks.removeIf(pk -> segmentsEqual(pk, primaryKey));
131→            if (pks.isEmpty()) {
132→                entries.remove(encoded);
133→            }
134→        }
135→    }
136→
137→    private Iterator<MemorySegment> lookupEq(Object value) {
138→        FieldType fieldType = inferFieldType(value);
139→        ByteArrayKey encoded = encodeKey(value, fieldType);
140→        List<MemorySegment> pks = entries.get(encoded);
141→        if (pks == null || pks.isEmpty()) {
142→            return Collections.emptyIterator();
143→        }
144→        return List.copyOf(pks).iterator();
145→    }
146→
147→    private Iterator<MemorySegment> lookupNe(Object value) {
148→        FieldType fieldType = inferFieldType(value);
149→        ByteArrayKey excluded = encodeKey(value, fieldType);
150→        List<MemorySegment> result = new ArrayList<>();
151→        for (var entry : entries.entrySet()) {
152→            if (!entry.getKey().equals(excluded)) {
153→                result.addAll(entry.getValue());
154→            }
155→        }
156→        return result.iterator();
157→    }
158→
159→    private Iterator<MemorySegment> lookupGt(Object value) {
160→        FieldType fieldType = inferFieldType(value);
161→        ByteArrayKey encoded = encodeKey(value, fieldType);
162→        return flattenValues(entries.tailMap(encoded, false));
163→    }
164→
165→    private Iterator<MemorySegment> lookupGte(Object value) {
166→        FieldType fieldType = inferFieldType(value);
167→        ByteArrayKey encoded = encodeKey(value, fieldType);
168→        return flattenValues(entries.tailMap(encoded, true));
169→    }
170→
171→    private Iterator<MemorySegment> lookupLt(Object value) {
172→        FieldType fieldType = inferFieldType(value);
173→        ByteArrayKey encoded = encodeKey(value, fieldType);
174→        return flattenValues(entries.headMap(encoded, false));
175→    }
176→
177→    private Iterator<MemorySegment> lookupLte(Object value) {
178→        FieldType fieldType = inferFieldType(value);
179→        ByteArrayKey encoded = encodeKey(value, fieldType);
180→        return flattenValues(entries.headMap(encoded, true));
181→    }
182→
183→    private Iterator<MemorySegment> lookupBetween(Object low, Object high) {
184→        FieldType fieldType = inferFieldType(low);
185→        ByteArrayKey lowKey = encodeKey(low, fieldType);
186→        ByteArrayKey highKey = encodeKey(high, fieldType);
187→        return flattenValues(entries.subMap(lowKey, true, highKey, true));
188→    }
189→
190→    private static Iterator<MemorySegment> flattenValues(
191→            NavigableMap<ByteArrayKey, List<MemorySegment>> map) {
192→        List<MemorySegment> result = new ArrayList<>();
193→        for (List<MemorySegment> pks : map.values()) {
194→            result.addAll(pks);
195→        }
196→        return result.iterator();
197→    }
198→
199→    private static ByteArrayKey encodeKey(Object value, FieldType fieldType) {
200→        MemorySegment encoded = FieldValueCodec.encode(value, fieldType);
201→        return new ByteArrayKey(encoded.toArray(ValueLayout.JAVA_BYTE));
202→    }
203→
204→    private static MemorySegment copySegment(MemorySegment src) {
205→        MemorySegment copy = Arena.ofAuto().allocate(src.byteSize());
206→        copy.copyFrom(src);
207→        return copy;
208→    }
209→
210→    private static boolean segmentsEqual(MemorySegment a, MemorySegment b) {
211→        return a.byteSize() == b.byteSize() && a.mismatch(b) == -1;
212→    }
213→
214→    private static String predicateField(Predicate predicate) {
215→        return switch (predicate) {
216→            case Predicate.Eq eq -> eq.field();
217→            case Predicate.Ne ne -> ne.field();
218→            case Predicate.Gt gt -> gt.field();
219→            case Predicate.Gte gte -> gte.field();
220→            case Predicate.Lt lt -> lt.field();
221→            case Predicate.Lte lte -> lte.field();
222→            case Predicate.Between between -> between.field();
223→            case Predicate.FullTextMatch ftm -> ftm.field();
224→            case Predicate.VectorNearest vn -> vn.field();
225→            case Predicate.And _, Predicate.Or _ -> null;
226→        };
227→    }
228→
229→    static FieldType inferFieldType(Object value) {
230→        return switch (value) {
231→            case String _ -> FieldType.Primitive.STRING;
232→            case Integer _ -> FieldType.Primitive.INT32;
233→            case Long _ -> FieldType.Primitive.INT64;
234→            case Short _ -> FieldType.Primitive.INT16;
235→            case Byte _ -> FieldType.Primitive.INT8;
236→            case Float _ -> FieldType.Primitive.FLOAT32;
237→            case Double _ -> FieldType.Primitive.FLOAT64;
238→            case Boolean _ -> FieldType.Primitive.BOOLEAN;
239→            default -> throw new IllegalArgumentException(
240→                    "Cannot infer field type for: " + value.getClass().getSimpleName());
241→        };
242→    }
243→
244→    /**
245→     * Byte array wrapper with unsigned bytewise comparison for use as TreeMap key.
246→     */
247→    record ByteArrayKey(byte[] data) implements Comparable<ByteArrayKey> {
248→
249→        @Override
250→        public int compareTo(ByteArrayKey other) {
251→            int len = Math.min(this.data.length, other.data.length);
252→            for (int i = 0; i < len; i++) {
253→                int cmp = Byte.toUnsignedInt(this.data[i]) - Byte.toUnsignedInt(other.data[i]);
254→                if (cmp != 0) {
255→                    return cmp;
256→                }
257→            }
258→            return Integer.compare(this.data.length, other.data.length);
259→        }
260→
261→        @Override
262→        public boolean equals(Object obj) {
263→            if (this == obj) {
264→                return true;
265→            }
266→            if (!(obj instanceof ByteArrayKey other)) {
267→                return false;
268→            }
269→            return java.util.Arrays.equals(this.data, other.data);
270→        }
271→
272→        @Override
273→        public int hashCode() {
274→            return java.util.Arrays.hashCode(data);
275→        }
276→    }
277→}
