  1→package jlsm.table.internal;
  2→
  3→import jlsm.core.io.MemorySerializer;
  4→import jlsm.core.model.Entry;
  5→import jlsm.core.tree.TypedLsmTree;
  6→import jlsm.table.DuplicateKeyException;
  7→import jlsm.table.JlsmDocument;
  8→import jlsm.table.JlsmSchema;
  9→import jlsm.table.JlsmTable;
 10→import jlsm.table.KeyNotFoundException;
 11→import jlsm.table.TableEntry;
 12→import jlsm.table.UpdateMode;
 13→
 14→import java.io.IOException;
 15→import java.lang.foreign.ValueLayout;
 16→import java.nio.charset.StandardCharsets;
 17→import java.util.Iterator;
 18→import java.util.NoSuchElementException;
 19→import java.util.Objects;
 20→import java.util.Optional;
 21→
 22→/**
 23→ * String-keyed {@link JlsmTable} implementation backed by a {@link TypedLsmTree.StringKeyed}.
 24→ */
 25→public final class StringKeyedTable implements JlsmTable.StringKeyed {
 26→
 27→    private final TypedLsmTree.StringKeyed<JlsmDocument> tree;
 28→    private final MemorySerializer<JlsmDocument> codec;
 29→
 30→    /**
 31→     * Constructs a new StringKeyedTable.
 32→     *
 33→     * @param tree the backing LSM tree; must not be null
 34→     * @param codec the document serializer for scan value deserialization; must not be null
 35→     * @param schema the optional schema (may be null)
 36→     */
 37→    public StringKeyedTable(TypedLsmTree.StringKeyed<JlsmDocument> tree,
 38→            MemorySerializer<JlsmDocument> codec, JlsmSchema schema) {
 39→        assert tree != null : "tree must not be null";
 40→        assert codec != null : "codec must not be null";
 41→        this.tree = tree;
 42→        this.codec = codec;
 43→    }
 44→
 45→    @Override
 46→    public void create(String key, JlsmDocument doc) throws IOException {
 47→        Objects.requireNonNull(key, "key must not be null");
 48→        Objects.requireNonNull(doc, "doc must not be null");
 49→
 50→        final Optional<JlsmDocument> existing = tree.get(key);
 51→        if (existing.isPresent()) {
 52→            throw new DuplicateKeyException(key);
 53→        }
 54→        tree.put(key, doc);
 55→    }
 56→
 57→    @Override
 58→    public Optional<JlsmDocument> get(String key) throws IOException {
 59→        Objects.requireNonNull(key, "key must not be null");
 60→        return tree.get(key);
 61→    }
 62→
 63→    @Override
 64→    public void update(String key, JlsmDocument doc, UpdateMode mode) throws IOException {
 65→        Objects.requireNonNull(key, "key must not be null");
 66→        Objects.requireNonNull(doc, "doc must not be null");
 67→        Objects.requireNonNull(mode, "mode must not be null");
 68→
 69→        final Optional<JlsmDocument> existing = tree.get(key);
 70→        if (existing.isEmpty()) {
 71→            throw new KeyNotFoundException(key);
 72→        }
 73→
 74→        switch (mode) {
 75→            case REPLACE -> tree.put(key, doc);
 76→            case PATCH -> {
 77→                final JlsmDocument merged = mergeDocuments(existing.get(), doc);
 78→                tree.put(key, merged);
 79→            }
 80→        }
 81→    }
 82→
 83→    @Override
 84→    public void delete(String key) throws IOException {
 85→        Objects.requireNonNull(key, "key must not be null");
 86→        tree.delete(key);
 87→    }
 88→
 89→    @Override
 90→    public Iterator<TableEntry<String>> getAllInRange(String from, String to) throws IOException {
 91→        Objects.requireNonNull(from, "from must not be null");
 92→        Objects.requireNonNull(to, "to must not be null");
 93→
 94→        final Iterator<Entry> rawEntries = tree.scan(from, to);
 95→        return new Iterator<>() {
 96→            private TableEntry<String> next;
 97→
 98→            {
 99→                advance();
100→            }
101→
102→            private void advance() {
103→                next = null;
104→                while (rawEntries.hasNext()) {
105→                    final Entry entry = rawEntries.next();
106→                    if (entry instanceof Entry.Put put) {
107→                        final String decodedKey = new String(
108→                                entry.key().toArray(ValueLayout.JAVA_BYTE), StandardCharsets.UTF_8);
109→                        final JlsmDocument doc = codec.deserialize(put.value());
110→                        next = new TableEntry<>(decodedKey, doc);
111→                        return;
112→                    }
113→                    // Skip Entry.Delete tombstones
114→                }
115→            }
116→
117→            @Override
118→            public boolean hasNext() {
119→                return next != null;
120→            }
121→
122→            @Override
123→            public TableEntry<String> next() {
124→                if (next == null) {
125→                    throw new NoSuchElementException();
126→                }
127→                final TableEntry<String> current = next;
128→                advance();
129→                return current;
130→            }
131→        };
132→    }
133→
134→    @Override
135→    public void close() throws IOException {
136→        tree.close();
137→    }
138→
139→    // -------------------------------------------------------------------------
140→    // Internal helpers
141→    // -------------------------------------------------------------------------
142→
143→    private static JlsmDocument mergeDocuments(JlsmDocument existing, JlsmDocument patch) {
144→        final Object[] existingVals = DocumentAccess.get().values(existing);
145→        final Object[] newVals = DocumentAccess.get().values(patch);
146→        assert existingVals.length == newVals.length
147→                : "existing and patch value arrays must have the same length";
148→        final Object[] merged = new Object[existingVals.length];
149→        for (int i = 0; i < merged.length; i++) {
150→            merged[i] = newVals[i] != null ? newVals[i] : existingVals[i];
151→        }
152→        return DocumentAccess.get().create(existing.schema(), merged);
153→    }
154→}
