  3→import java.util.List;
  4→import java.util.Objects;
  5→
  6→/**
  7→ * A query predicate AST node. Predicates form a tree that the query executor inspects to select
  8→ * indices and build execution plans.
  9→ *
 10→ * <p>
 11→ * Designed to be inspectable and serializable for future SQL translation.
 12→ *
 13→ * <p>
 14→ * Contract:
 15→ * <ul>
 16→ * <li>All leaf predicates carry a field name and typed value(s)</li>
 17→ * <li>Composite predicates (And, Or) hold a list of child predicates</li>
 18→ * <li>Field name and type compatibility validated eagerly at construction</li>
 19→ * </ul>
 20→ */
 21→public sealed interface Predicate {
 22→
 23→    /** Equality: field == value. Usable with any primitive field type. */
 24→    record Eq(String field, Object value) implements Predicate {
 25→        public Eq {
 26→            Objects.requireNonNull(field);
 27→            Objects.requireNonNull(value);
 28→        }
 29→    }
 30→
 31→    /** Inequality: field != value. Usable with any primitive field type. */
 32→    record Ne(String field, Object value) implements Predicate {
 33→        public Ne {
 34→            Objects.requireNonNull(field);
 35→            Objects.requireNonNull(value);
 36→        }
 37→    }
 38→
 39→    /** Greater than: field > value. Requires an ordered field type. */
 40→    record Gt(String field, Comparable<?> value) implements Predicate {
 41→        public Gt {
 42→            Objects.requireNonNull(field);
 43→            Objects.requireNonNull(value);
 44→        }
 45→    }
 46→
 47→    /** Greater than or equal: field >= value. Requires an ordered field type. */
 48→    record Gte(String field, Comparable<?> value) implements Predicate {
 49→        public Gte {
 50→            Objects.requireNonNull(field);
 51→            Objects.requireNonNull(value);
 52→        }
 53→    }
 54→
 55→    /** Less than: field < value. Requires an ordered field type. */
 56→    record Lt(String field, Comparable<?> value) implements Predicate {
 57→        public Lt {
