324→    // IvfFlat implementation
325→    // -----------------------------------------------------------------------
326→
327→    /**
328→     * Inverted File Flat (IVF-Flat) vector index.
329→     *
330→     * <h2>Key namespaces within the backing {@link LsmTree}</h2>
331→     *
332→     * <pre>
333→     *   [0x00][4-byte BE centroid_id]               → dim×4 bytes (centroid float32 coords)
334→     *   [0x01][4-byte BE centroid_id][doc_id_bytes] → dim×precision bytes (vector coords)
335→     *   [0x02][doc_id_bytes]                        → 4-byte BE centroid_id (reverse lookup)
336→     * </pre>
337→     *
338→     * <h2>Clustering strategy</h2> The first {@code numClusters} indexed vectors become centroids.
339→     * Subsequent vectors are assigned to the nearest centroid (using the configured
340→     * {@link SimilarityFunction}).
341→     */
342→    public static final class IvfFlat<D> implements VectorIndex.IvfFlat<D> {
343→
344→        // Key namespace prefix bytes
345→        private static final byte CENTROID_PREFIX = 0x00;
346→        private static final byte POSTING_PREFIX = 0x01;
347→        private static final byte REVERSE_PREFIX = 0x02;
348→
349→        // Scan bounds: [CENTROID_PREFIX, POSTING_PREFIX) covers all centroid keys
350→        private static final MemorySegment CENTROID_SCAN_START = MemorySegment
351→                .ofArray(new byte[]{ CENTROID_PREFIX });
352→        private static final MemorySegment CENTROID_SCAN_END = MemorySegment
353→                .ofArray(new byte[]{ POSTING_PREFIX });
354→
355→        private final LsmTree lsmTree;
356→        private final MemorySerializer<D> docIdSerializer;
357→        private final int dimensions;
358→        private final SimilarityFunction similarityFunction;
359→        private final int numClusters;
360→        private final int nprobe;
361→        private final VectorPrecision precision;
362→
363→        private IvfFlat(LsmTree lsmTree, MemorySerializer<D> docIdSerializer, int dimensions,
364→                SimilarityFunction similarityFunction, int numClusters, int nprobe,
365→                VectorPrecision precision) {
366→            assert lsmTree != null;
367→            assert docIdSerializer != null;
368→            assert dimensions > 0;
369→            assert similarityFunction != null;
370→            assert numClusters > 0;
371→            assert nprobe > 0;
372→            assert precision != null;
373→            this.lsmTree = lsmTree;
374→            this.docIdSerializer = docIdSerializer;
375→            this.dimensions = dimensions;
376→            this.similarityFunction = similarityFunction;
377→            this.numClusters = numClusters;
378→            this.nprobe = nprobe;
379→            this.precision = precision;
380→        }
381→
382→        @Override
383→        public VectorPrecision precision() {
384→            return precision;
385→        }
386→
387→        @Override
388→        public void index(D docId, float[] vector) throws IOException {
389→            Objects.requireNonNull(docId, "docId must not be null");
390→            Objects.requireNonNull(vector, "vector must not be null");
391→            if (vector.length != dimensions) {
392→                throw new IllegalArgumentException(
393→                        "vector.length=" + vector.length + " != dimensions=" + dimensions);
394→            }
395→
396→            byte[] docIdBytes = docIdSerializer.serialize(docId).toArray(ValueLayout.JAVA_BYTE);
397→            byte[] vectorBytes = encodeVector(vector, precision);
398→
399→            int centroidId = assignCentroid(vector);
400→
401→            // Store posting: [0x01][centroid_id][docId] → vector
402→            lsmTree.put(MemorySegment.ofArray(postingKey(centroidId, docIdBytes)),
403→                    MemorySegment.ofArray(vectorBytes));
404→
405→            // Store reverse lookup: [0x02][docId] → centroid_id (4 bytes BE)
406→            lsmTree.put(MemorySegment.ofArray(reverseKey(docIdBytes)),
407→                    MemorySegment.ofArray(encodeCentroidId(centroidId)));
408→        }
409→
410→        @Override
411→        public void remove(D docId) throws IOException {
412→            Objects.requireNonNull(docId, "docId must not be null");
413→
414→            byte[] docIdBytes = docIdSerializer.serialize(docId).toArray(ValueLayout.JAVA_BYTE);
415→            byte[] revKey = reverseKey(docIdBytes);
416→
417→            Optional<MemorySegment> revOpt = lsmTree.get(MemorySegment.ofArray(revKey));
418→            if (revOpt.isEmpty())
419→                return; // not indexed
420→
421→            int centroidId = decodeCentroidId(revOpt.get().toArray(ValueLayout.JAVA_BYTE), 0);
422→
423→            lsmTree.delete(MemorySegment.ofArray(postingKey(centroidId, docIdBytes)));
424→            lsmTree.delete(MemorySegment.ofArray(revKey));
425→        }
426→
427→        @Override
428→        public List<VectorIndex.SearchResult<D>> search(float[] query, int topK)
429→                throws IOException {
430→            Objects.requireNonNull(query, "query must not be null");
431→            if (query.length != dimensions) {
432→                throw new IllegalArgumentException(
433→                        "query.length=" + query.length + " != dimensions=" + dimensions);
434→            }
435→            if (topK <= 0)
436→                throw new IllegalArgumentException("topK must be > 0");
437→
438→            // Load all centroids
439→            List<float[]> centroidVecs = new ArrayList<>();
440→            List<Integer> centroidIds = new ArrayList<>();
441→            Iterator<Entry> centIt = lsmTree.scan(CENTROID_SCAN_START, CENTROID_SCAN_END);
442→            while (centIt.hasNext()) {
443→                Entry entry = centIt.next();
444→                if (!(entry instanceof Entry.Put put))
445→                    continue;
446→                byte[] key = entry.key().toArray(ValueLayout.JAVA_BYTE);
447→                if (key.length != 5 || key[0] != CENTROID_PREFIX)
448→                    continue;
449→                int cid = decodeCentroidId(key, 1);
450→                float[] cVec = decodeFloats(put.value().toArray(ValueLayout.JAVA_BYTE), dimensions);
451→                centroidVecs.add(cVec);
452→                centroidIds.add(cid);
453→            }
454→
455→            if (centroidVecs.isEmpty())
456→                return List.of();
457→
458→            // Score centroids, pick top nprobe
459→            int actualNprobe = Math.min(nprobe, centroidVecs.size());
460→            int[] nearestCentroidIds = topNCentroids(query, centroidVecs, centroidIds,
461→                    actualNprobe);
462→
463→            // Accumulate candidates from posting lists (min-heap to evict worst when over topK)
464→            PriorityQueue<ScoredCandidate> heap = new PriorityQueue<>(
465→                    Comparator.comparingDouble(ScoredCandidate::score)); // min at head for eviction
466→
467→            for (int cid : nearestCentroidIds) {
468→                byte[] postStart = postingKey(cid, new byte[0]);
469→                byte[] postEnd = postingEndKey(cid);
470→
471→                Iterator<Entry> postIt = lsmTree.scan(MemorySegment.ofArray(postStart),
472→                        MemorySegment.ofArray(postEnd));
473→
474→                while (postIt.hasNext()) {
475→                    Entry entry = postIt.next();
476→                    if (!(entry instanceof Entry.Put put))
477→                        continue; // skip tombstones
478→
479→                    byte[] key = entry.key().toArray(ValueLayout.JAVA_BYTE);
480→                    if (key.length <= 5 || key[0] != POSTING_PREFIX)
481→                        continue;
482→
483→                    byte[] docIdBytes = Arrays.copyOfRange(key, 5, key.length);
484→                    float[] vec = decodeVector(put.value().toArray(ValueLayout.JAVA_BYTE),
485→                            dimensions, precision);
486→                    float s = score(query, vec, similarityFunction);
487→
488→                    heap.add(new ScoredCandidate(docIdBytes, s));
489→                    if (heap.size() > topK)
490→                        heap.poll(); // evict worst
491→                }
492→            }
493→
494→            // Drain heap in descending order
495→            List<ScoredCandidate> sorted = new ArrayList<>(heap);
496→            sorted.sort((a, b) -> Float.compare(b.score(), a.score()));
497→
498→            List<VectorIndex.SearchResult<D>> results = new ArrayList<>(sorted.size());
499→            for (ScoredCandidate c : sorted) {
500→                D id = docIdSerializer.deserialize(MemorySegment.ofArray(c.docIdBytes()));
501→                results.add(new VectorIndex.SearchResult<>(id, c.score()));
502→            }
503→            return results;
504→        }
505→
506→        @Override
507→        public void close() throws IOException {
508→            lsmTree.close();
509→        }
510→
511→        // --- Key construction helpers ---
512→
513→        private static byte[] centroidKey(int centroidId) {
514→            return new byte[]{ CENTROID_PREFIX, (byte) (centroidId >>> 24),
515→                    (byte) (centroidId >>> 16), (byte) (centroidId >>> 8), (byte) centroidId };
516→        }
517→
518→        private static byte[] postingKey(int centroidId, byte[] docIdBytes) {
519→            byte[] key = new byte[5 + docIdBytes.length];
520→            key[0] = POSTING_PREFIX;
521→            key[1] = (byte) (centroidId >>> 24);
522→            key[2] = (byte) (centroidId >>> 16);
523→            key[3] = (byte) (centroidId >>> 8);
524→            key[4] = (byte) centroidId;
525→            System.arraycopy(docIdBytes, 0, key, 5, docIdBytes.length);
526→            return key;
527→        }
528→
529→        private static byte[] postingEndKey(int centroidId) {
530→            long next = (centroidId & 0xFFFFFFFFL) + 1L;
531→            if (next > 0xFFFFFFFFL) {
532→                return new byte[]{ REVERSE_PREFIX }; // overflow → next prefix byte
533→            }
534→            return new byte[]{ POSTING_PREFIX, (byte) (next >>> 24), (byte) (next >>> 16),
535→                    (byte) (next >>> 8), (byte) next };
536→        }
537→
538→        private static byte[] reverseKey(byte[] docIdBytes) {
539→            byte[] key = new byte[1 + docIdBytes.length];
540→            key[0] = REVERSE_PREFIX;
541→            System.arraycopy(docIdBytes, 0, key, 1, docIdBytes.length);
542→            return key;
543→        }
544→
545→        private static byte[] encodeCentroidId(int centroidId) {
546→            return new byte[]{ (byte) (centroidId >>> 24), (byte) (centroidId >>> 16),
547→                    (byte) (centroidId >>> 8), (byte) centroidId };
548→        }
549→
550→        private static int decodeCentroidId(byte[] bytes, int offset) {
551→            return ((bytes[offset] & 0xFF) << 24) | ((bytes[offset + 1] & 0xFF) << 16)
552→                    | ((bytes[offset + 2] & 0xFF) << 8) | (bytes[offset + 3] & 0xFF);
553→        }
554→
555→        // --- Centroid assignment ---
556→
557→        /**
558→         * Returns the centroid ID to assign to a new vector. Creates a new centroid if fewer than
559→         * {@code numClusters} centroids exist; otherwise assigns to the most similar existing one.
560→         */
561→        private int assignCentroid(float[] vector) throws IOException {
562→            List<float[]> centroids = new ArrayList<>();
563→            List<Integer> centroidIdList = new ArrayList<>();
564→
565→            Iterator<Entry> it = lsmTree.scan(CENTROID_SCAN_START, CENTROID_SCAN_END);
566→            while (it.hasNext()) {
567→                Entry entry = it.next();
568→                if (!(entry instanceof Entry.Put put))
569→                    continue;
570→                byte[] key = entry.key().toArray(ValueLayout.JAVA_BYTE);
571→                if (key.length != 5 || key[0] != CENTROID_PREFIX)
572→                    continue;
573→                int cid = decodeCentroidId(key, 1);
574→                float[] cVec = decodeFloats(put.value().toArray(ValueLayout.JAVA_BYTE), dimensions);
575→                centroids.add(cVec);
576→                centroidIdList.add(cid);
577→            }
578→
579→            if (centroids.size() < numClusters) {
580→                int newCid = centroids.size(); // sequential 0-based centroid IDs
581→                lsmTree.put(MemorySegment.ofArray(centroidKey(newCid)),
582→                        MemorySegment.ofArray(encodeFloats(vector)));
583→                return newCid;
584→            }
585→
586→            return nearestCentroid(vector, centroids, centroidIdList);
587→        }
588→
589→        private int nearestCentroid(float[] vector, List<float[]> centroids, List<Integer> ids) {
590→            int best = ids.get(0);
591→            float bestScore = score(vector, centroids.get(0), similarityFunction);
592→            for (int i = 1; i < centroids.size(); i++) {
593→                float s = score(vector, centroids.get(i), similarityFunction);
594→                if (s > bestScore) {
595→                    bestScore = s;
596→                    best = ids.get(i);
597→                }
598→            }
599→            return best;

600→        }
601→
602→        private int[] topNCentroids(float[] query, List<float[]> centroids, List<Integer> ids,
603→                int n) {
604→            float[] scores = new float[centroids.size()];
605→            for (int i = 0; i < centroids.size(); i++) {
606→                scores[i] = score(query, centroids.get(i), similarityFunction);
607→            }
608→            Integer[] indices = new Integer[centroids.size()];
609→            for (int i = 0; i < indices.length; i++)
610→                indices[i] = i;
611→            Arrays.sort(indices, (a, b) -> Float.compare(scores[b], scores[a])); // descending
612→
613→            int[] result = new int[n];
614→            for (int i = 0; i < n; i++)
615→                result[i] = ids.get(indices[i]);
616→            return result;
617→        }
