655→    /**
656→     * Hierarchical Navigable Small World (HNSW) graph vector index.
657→     *
658→     * <h2>Key namespaces within the backing {@link LsmTree}</h2>
659→     *
660→     * <pre>
661→     *   [doc_id_bytes]          → node value (see below) — node data
662→     *   [0xFE]                  → [4-byte BE max_layer][doc_id_bytes] — entry point
663→     *   [0xFF][doc_id_bytes]    → empty segment — soft-delete tombstone
664→     * </pre>
665→     *
666→     * <h2>Node value encoding</h2>
667→     *
668→     * <pre>
669→     *   [4-byte BE docIdBytesLen]
670→     *   [4-byte BE layerCount]
671→     *   for each layer l = 0..layerCount-1:
672→     *     [4-byte BE neighborCount_l]
673→     *     [neighborCount_l × docIdBytesLen bytes]
674→     *   [dim × precision.bytesPerComponent() bytes] — vector encoded per VectorPrecision
675→     * </pre>
676→     *
677→     * <h2>Soft-delete</h2> {@link #remove} writes a soft-delete key {@code [0xFF][docId]}. During
678→     * search, soft-deleted nodes are skipped in result collection.
679→     */
680→    public static final class Hnsw<D> implements VectorIndex.Hnsw<D> {
681→
682→        private static final byte[] ENTRY_POINT_KEY = new byte[]{ (byte) 0xFE };
683→        private static final byte SOFT_DELETE_PREFIX = (byte) 0xFF;
684→
685→        private final LsmTree lsmTree;
686→        private final MemorySerializer<D> docIdSerializer;
687→        private final int dimensions;
688→        private final SimilarityFunction similarityFunction;
689→        private final int maxConnections;
690→        private final int efConstruction;
691→        private final int efSearch;
692→        private final VectorPrecision precision;
693→        private final Random random = new Random();
694→
695→        private Hnsw(LsmTree lsmTree, MemorySerializer<D> docIdSerializer, int dimensions,
696→                SimilarityFunction similarityFunction, int maxConnections, int efConstruction,
697→                int efSearch, VectorPrecision precision) {
698→            assert lsmTree != null;
699→            assert docIdSerializer != null;
700→            assert dimensions > 0;
701→            assert similarityFunction != null;
702→            assert maxConnections > 0;
703→            assert efConstruction > 0;
704→            assert efSearch > 0;
705→            assert precision != null;
706→            this.lsmTree = lsmTree;
707→            this.docIdSerializer = docIdSerializer;
708→            this.dimensions = dimensions;
709→            this.similarityFunction = similarityFunction;
710→            this.maxConnections = maxConnections;
711→            this.efConstruction = efConstruction;
712→            this.efSearch = efSearch;
713→            this.precision = precision;
714→        }
715→
716→        @Override
717→        public VectorPrecision precision() {
718→            return precision;
719→        }
