721→        @Override
722→        public void index(D docId, float[] vector) throws IOException {
723→            Objects.requireNonNull(docId, "docId must not be null");
724→            Objects.requireNonNull(vector, "vector must not be null");
725→            if (vector.length != dimensions) {
726→                throw new IllegalArgumentException(
727→                        "vector.length=" + vector.length + " != dimensions=" + dimensions);
728→            }
729→
730→            byte[] docIdBytes = docIdSerializer.serialize(docId).toArray(ValueLayout.JAVA_BYTE);
731→            int newLevel = randomLevel();
732→
733→            EntryPoint ep = readEntryPoint();
734→
735→            if (ep == null) {
736→                // First node: create empty layer list and set as entry point
737→                List<List<byte[]>> layers = new ArrayList<>();
738→                for (int l = 0; l <= newLevel; l++)
739→                    layers.add(new ArrayList<>());
740→                lsmTree.put(MemorySegment.ofArray(docIdBytes),
741→                        MemorySegment.ofArray(encodeNode(docIdBytes, layers, vector, precision)));
742→                lsmTree.put(MemorySegment.ofArray(ENTRY_POINT_KEY),
743→                        MemorySegment.ofArray(encodeEntryPoint(docIdBytes, newLevel)));
744→                return;
745→            }
746→
747→            int maxLayer = ep.maxLayer();
748→            byte[] currentEp = ep.docIdBytes();
749→
750→            // Phase 1: traverse from maxLayer down to newLevel+1, greedy (ef=1)
751→            for (int lc = maxLayer; lc > newLevel; lc--) {
752→                currentEp = greedySearch1(currentEp, vector, lc);
753→            }
754→
755→            // Phase 2: from min(newLevel, maxLayer) down to 0, collect neighbors
756→            int startLevel = Math.min(newLevel, maxLayer);
757→            List<List<byte[]>> newNodeLayers = new ArrayList<>();
758→            for (int l = 0; l <= newLevel; l++)
759→                newNodeLayers.add(new ArrayList<>());
760→
761→            for (int lc = startLevel; lc >= 0; lc--) {
762→                List<ScoredCandidate> candidates = searchLayer(currentEp, vector, efConstruction,
763→                        lc);
764→                List<byte[]> selectedNeighbors = selectNeighbors(candidates, maxConnections);
765→                newNodeLayers.set(lc, selectedNeighbors);
766→
767→                // Update currentEp for next (lower) layer: best candidate in this layer
768→                if (!candidates.isEmpty()) {
769→                    ScoredCandidate best = candidates.stream()
770→                            .max(Comparator.comparingDouble(ScoredCandidate::score)).orElseThrow();
771→                    currentEp = best.docIdBytes();
772→                }
773→
774→                // Bidirectional neighbor updates
775→                for (byte[] nbId : selectedNeighbors) {
776→                    Optional<MemorySegment> nbOpt = lsmTree.get(MemorySegment.ofArray(nbId));
777→                    if (nbOpt.isEmpty())
778→                        continue;
779→
780→                    DecodedNode nbNode = decodeNode(nbOpt.get().toArray(ValueLayout.JAVA_BYTE),
781→                            precision);
782→                    if (lc >= nbNode.layerNeighbors().size())
783→                        continue;
784→
785→                    List<List<byte[]>> updatedLayers = new ArrayList<>(nbNode.layerNeighbors());
786→                    List<byte[]> updatedNbrs = new ArrayList<>(updatedLayers.get(lc));
787→                    updatedNbrs.add(docIdBytes);
788→
789→                    if (updatedNbrs.size() > maxConnections) {
790→                        updatedNbrs = trimToM(nbNode.vector(), updatedNbrs, maxConnections);
791→                    }
792→
793→                    updatedLayers.set(lc, updatedNbrs);
794→                    lsmTree.put(MemorySegment.ofArray(nbId), MemorySegment
795→                            .ofArray(encodeNode(nbId, updatedLayers, nbNode.vector(), precision)));
796→                }
797→            }
798→
799→            // Write new node
800→            lsmTree.put(MemorySegment.ofArray(docIdBytes), MemorySegment
801→                    .ofArray(encodeNode(docIdBytes, newNodeLayers, vector, precision)));
802→
803→            // Promote entry point if this node has a higher level
804→            if (newLevel > maxLayer) {
805→                lsmTree.put(MemorySegment.ofArray(ENTRY_POINT_KEY),
806→                        MemorySegment.ofArray(encodeEntryPoint(docIdBytes, newLevel)));
807→            }
808→        }
