810→        @Override
811→        public void remove(D docId) throws IOException {
812→            Objects.requireNonNull(docId, "docId must not be null");
813→            byte[] docIdBytes = docIdSerializer.serialize(docId).toArray(ValueLayout.JAVA_BYTE);
814→            // Soft delete: write tombstone at [0xFF][docId]
815→            lsmTree.put(MemorySegment.ofArray(softDeleteKey(docIdBytes)), MemorySegment.NULL);
816→        }
