818→        @Override
819→        public List<VectorIndex.SearchResult<D>> search(float[] query, int topK)
820→                throws IOException {
821→            Objects.requireNonNull(query, "query must not be null");
822→            if (query.length != dimensions) {
823→                throw new IllegalArgumentException(
824→                        "query.length=" + query.length + " != dimensions=" + dimensions);
825→            }
826→            if (topK <= 0)
827→                throw new IllegalArgumentException("topK must be > 0");
828→
829→            EntryPoint ep = readEntryPoint();
830→            if (ep == null)
831→                return List.of();
832→
833→            // Optional prefetch hint for the entry point
834→            if (lsmTree instanceof PrefetchHint ph) {
835→                ph.prefetch(List.of(MemorySegment.ofArray(ep.docIdBytes())));
836→            }
837→
838→            byte[] currentEp = ep.docIdBytes();
839→
840→            // Phase 1: from maxLayer down to 1, greedy
841→            for (int lc = ep.maxLayer(); lc > 0; lc--) {
842→                currentEp = greedySearch1(currentEp, query, lc);
843→            }
844→
845→            // Phase 2: layer 0 with efSearch
846→            List<ScoredCandidate> candidates = searchLayer(currentEp, query, efSearch, 0);
847→
848→            // Sort descending, filter soft-deleted, take topK
849→            candidates.sort((a, b) -> Float.compare(b.score(), a.score()));
850→
851→            List<VectorIndex.SearchResult<D>> results = new ArrayList<>();
852→            for (ScoredCandidate c : candidates) {
853→                if (results.size() >= topK)
854→                    break;
855→                if (isSoftDeleted(c.docIdBytes()))
856→                    continue;
857→                D id = docIdSerializer.deserialize(MemorySegment.ofArray(c.docIdBytes()));
858→                results.add(new VectorIndex.SearchResult<>(id, c.score()));
859→            }
860→            return results;
861→        }
