868→        // --- HNSW helpers ---
869→
870→        private int randomLevel() {
871→            // Floor(-ln(U[0,1]) / ln(maxConnections)) — standard HNSW level assignment
872→            double mL = 1.0 / Math.log(maxConnections);
873→            int level = (int) (-Math.log(Math.max(1e-10, random.nextDouble())) * mL);
874→            return Math.min(level, 16); // cap to prevent degenerate cases
875→        }
