877→        private record EntryPoint(byte[] docIdBytes, int maxLayer) {
878→        }
879→
880→        private EntryPoint readEntryPoint() throws IOException {
881→            Optional<MemorySegment> opt = lsmTree.get(MemorySegment.ofArray(ENTRY_POINT_KEY));
882→            if (opt.isEmpty())
883→                return null;
884→            byte[] value = opt.get().toArray(ValueLayout.JAVA_BYTE);
885→            int maxLayer = readInt(value, 0);
886→            byte[] docIdBytes = Arrays.copyOfRange(value, 4, value.length);
887→            return new EntryPoint(docIdBytes, maxLayer);
888→        }
889→
890→        private static byte[] encodeEntryPoint(byte[] docIdBytes, int maxLayer) {
891→            byte[] value = new byte[4 + docIdBytes.length];
892→            writeInt(value, 0, maxLayer);
893→            System.arraycopy(docIdBytes, 0, value, 4, docIdBytes.length);
894→            return value;
895→        }
896→
897→        /**
898→         * Greedily finds the single nearest node to {@code query} at {@code layer}, starting from
899→         * {@code entryDocId}. Returns the docId of the nearest found node.
900→         */
901→        private byte[] greedySearch1(byte[] entryDocId, float[] query, int layer)
902→                throws IOException {
903→            byte[] currentId = entryDocId;
904→            float currentScore = scoreNode(currentId, query);
905→
906→            boolean improved = true;
907→            while (improved) {
908→                improved = false;
909→                for (byte[] nbId : getNodeNeighbors(currentId, layer)) {
910→                    float s = scoreNode(nbId, query);
911→                    if (s > currentScore) {
912→                        currentScore = s;
913→                        currentId = nbId;
914→                        improved = true;
915→                    }
916→                }
917→            }
918→            return currentId;
919→        }
920→
921→        /**
922→         * Collects up to {@code ef} best candidates at {@code layer} starting from
923→         * {@code entryDocId}, using a best-first search with bounded candidate set.
924→         */
925→        private List<ScoredCandidate> searchLayer(byte[] entryDocId, float[] query, int ef,
926→                int layer) throws IOException {
927→            Set<ByteBuffer> visited = new HashSet<>();
928→            visited.add(ByteBuffer.wrap(entryDocId));
929→
930→            float entryScore = scoreNode(entryDocId, query);
931→
932→            // Expansion frontier: max-heap by score (expand best first)
933→            PriorityQueue<ScoredCandidate> frontier = new PriorityQueue<>(
934→                    (a, b) -> Float.compare(b.score(), a.score()));
935→            // Result set: min-heap by score (evict worst when over ef)
936→            PriorityQueue<ScoredCandidate> results = new PriorityQueue<>(
937→                    Comparator.comparingDouble(ScoredCandidate::score));
938→
939→            ScoredCandidate entry = new ScoredCandidate(entryDocId, entryScore);
940→            frontier.add(entry);
941→            results.add(entry);
942→
943→            while (!frontier.isEmpty()) {
944→                ScoredCandidate best = frontier.poll();
945→                float worstResult = results.isEmpty() ? Float.NEGATIVE_INFINITY
946→                        : results.peek().score();
947→
948→                // No candidate can improve results
949→                if (best.score() < worstResult && results.size() >= ef)
950→                    break;
951→
952→                for (byte[] nbId : getNodeNeighbors(best.docIdBytes(), layer)) {
953→                    ByteBuffer nbBuf = ByteBuffer.wrap(nbId);
954→                    if (!visited.add(nbBuf))
955→                        continue; // already visited
956→
957→                    float nbScore = scoreNode(nbId, query);
958→                    float currentWorst = results.isEmpty() ? Float.NEGATIVE_INFINITY
959→                            : results.peek().score();
960→
961→                    if (results.size() < ef || nbScore > currentWorst) {
962→                        ScoredCandidate nb = new ScoredCandidate(nbId, nbScore);
963→                        frontier.add(nb);
964→                        results.add(nb);
965→                        if (results.size() > ef)
966→                            results.poll();
967→                    }
968→                }
969→            }
970→
971→            return new ArrayList<>(results);
972→        }
973→
974→        private List<byte[]> selectNeighbors(List<ScoredCandidate> candidates, int maxM) {
975→            return candidates.stream().sorted((a, b) -> Float.compare(b.score(), a.score()))
976→                    .limit(maxM).map(ScoredCandidate::docIdBytes).collect(Collectors.toList());
977→        }
978→
979→        /**
980→         * Trims {@code neighbors} to at most {@code maxM}, keeping the {@code maxM} most similar to
981→         * {@code centerVec} according to the configured {@link SimilarityFunction}.
982→         */
983→        private List<byte[]> trimToM(float[] centerVec, List<byte[]> neighbors, int maxM)
984→                throws IOException {
985→            List<ScoredCandidate> scored = new ArrayList<>();
986→            for (byte[] nbId : neighbors) {
987→                Optional<MemorySegment> nbOpt = lsmTree.get(MemorySegment.ofArray(nbId));
988→                if (nbOpt.isEmpty())
989→                    continue;
990→                DecodedNode nbNode = decodeNode(nbOpt.get().toArray(ValueLayout.JAVA_BYTE),
991→                        precision);
992→                float s = score(centerVec, nbNode.vector(), similarityFunction);
993→                scored.add(new ScoredCandidate(nbId, s));
994→            }
995→            return selectNeighbors(scored, maxM);
996→        }
997→
998→        private float scoreNode(byte[] docIdBytes, float[] query) throws IOException {
999→            Optional<MemorySegment> opt = lsmTree.get(MemorySegment.ofArray(docIdBytes));

1000→            if (opt.isEmpty())
1001→                return Float.NEGATIVE_INFINITY;
1002→            DecodedNode node = decodeNode(opt.get().toArray(ValueLayout.JAVA_BYTE), precision);
1003→            return score(query, node.vector(), similarityFunction);
1004→        }
1005→
1006→        private List<byte[]> getNodeNeighbors(byte[] docIdBytes, int layer) throws IOException {
1007→            Optional<MemorySegment> opt = lsmTree.get(MemorySegment.ofArray(docIdBytes));
1008→            if (opt.isEmpty())
1009→                return List.of();
1010→            DecodedNode node = decodeNode(opt.get().toArray(ValueLayout.JAVA_BYTE), precision);
1011→            if (layer >= node.layerNeighbors().size())
1012→                return List.of();
1013→            return node.layerNeighbors().get(layer);
1014→        }
