1020→        private static byte[] softDeleteKey(byte[] docIdBytes) {
1021→            byte[] key = new byte[1 + docIdBytes.length];
1022→            key[0] = SOFT_DELETE_PREFIX;
1023→            System.arraycopy(docIdBytes, 0, key, 1, docIdBytes.length);
1024→            return key;
1025→        }
