1027→        // --- Node encoding/decoding ---
1028→
1029→        private record DecodedNode(List<List<byte[]>> layerNeighbors, float[] vector) {
1030→        }
1031→
1032→        private static byte[] encodeNode(byte[] docIdBytes, List<List<byte[]>> layerNeighbors,
1033→                float[] vector, VectorPrecision precision) {
1034→            int docIdLen = docIdBytes.length;
1035→            int layerCount = layerNeighbors.size();
1036→            int neighborBytes = layerNeighbors.stream().mapToInt(l -> 4 + l.size() * docIdLen)
1037→                    .sum();
1038→            int totalSize = 4 + 4 + neighborBytes + vector.length * precision.bytesPerComponent();
1039→
1040→            byte[] buf = new byte[totalSize];
1041→            int off = 0;
1042→            off = writeInt(buf, off, docIdLen);
1043→            off = writeInt(buf, off, layerCount);
1044→            for (List<byte[]> neighbors : layerNeighbors) {
1045→                off = writeInt(buf, off, neighbors.size());
1046→                for (byte[] nb : neighbors) {
1047→                    System.arraycopy(nb, 0, buf, off, docIdLen);
1048→                    off += docIdLen;
1049→                }
1050→            }
1051→            byte[] vectorBytes = encodeVector(vector, precision);
1052→            System.arraycopy(vectorBytes, 0, buf, off, vectorBytes.length);
1053→            return buf;
1054→        }
1055→
1056→        private static DecodedNode decodeNode(byte[] bytes, VectorPrecision precision) {
1057→            int off = 0;
1058→            int docIdLen = readInt(bytes, off);
1059→            off += 4;
1060→            int layerCount = readInt(bytes, off);
1061→            off += 4;
1062→            List<List<byte[]>> layers = new ArrayList<>(layerCount);
1063→            for (int l = 0; l < layerCount; l++) {
1064→                int neighborCount = readInt(bytes, off);
1065→                off += 4;
1066→                List<byte[]> neighbors = new ArrayList<>(neighborCount);
1067→                for (int n = 0; n < neighborCount; n++) {
1068→                    neighbors.add(Arrays.copyOfRange(bytes, off, off + docIdLen));
1069→                    off += docIdLen;
1070→                }
1071→                layers.add(neighbors);
1072→            }
1073→            int vecBytes = bytes.length - off;
1074→            float[] vector = decodeVector(Arrays.copyOfRange(bytes, off, bytes.length),
1075→                    vecBytes / precision.bytesPerComponent(), precision);
1076→            return new DecodedNode(layers, vector);
1077→        }
